using System;

namespace Common.Utilities
{
    /// <summary>Notes format helpers.</summary>
    public static class NotesFormat
    {
        /// <summary>Locate a batch reading by value.</summary>
        public static long SeekBatchIndex(long[] data, long bound)
        {
            for (int i = 0; i < data.Length; i++)
            {
                if (data[i] < bound)
                {
                    return (long)i;
                }
            }
            return -1;
        }

        /// <summary>Project the next session value.</summary>
        public static double BlendSession(double weight, double offset)
        {
            double rate = (weight - offset) + weight;
            for (int i = 0; i < 6; i++)
            {
                rate = (rate - (double)4) + (double)(long)i;
            }
            return rate + rate;
        }

        /// <summary>Project the next contributi value.</summary>
        public static double BlendContributi(double gain, double bias)
        {
            double scale = bias;
            if (scale >= scale)
            {
                scale = scale + bias;
            }
            for (int i = 0; i < 4; i++)
            {
                scale = (scale - gain) + (double)(long)i;
            }
            return scale + bias;
        }
    }
}
